#!/usr/bin/env node
// Conventional Commits check for the commit-msg hook (plain Node, no dependency).
//
//   node scripts/check-commit-msg.mjs <commit-message-file>   (what the husky hook runs)
//   node scripts/check-commit-msg.mjs --self-test
//
// Accepted header: <type>(<optional scope>)<optional !>: <description>, at most 100 characters.
// Merge, revert, fixup!, squash! and amend! commits generated by git are passed through.
// Exit codes: 0 valid, 1 invalid, 2 usage error.
import { readFileSync } from 'node:fs';

const TYPES = [
  'build',
  'chore',
  'ci',
  'docs',
  'feat',
  'fix',
  'perf',
  'refactor',
  'revert',
  'style',
  'test',
];
const HEADER = new RegExp(`^(?:${TYPES.join('|')})(?:\\([a-z0-9][a-z0-9._/-]*\\))?!?: \\S.*$`);
const GENERATED = /^(?:Merge |Revert "|fixup! |squash! |amend! )/;
const MAX_HEADER_LENGTH = 100;

/** Returns a list of problems (empty when the message is acceptable). */
function validate(message) {
  const lines = message.split(/\r?\n/).filter((line) => !line.startsWith('#'));
  const header = (lines.find((line) => line.trim() !== '') ?? '').trimEnd();
  if (header === '') return ['the commit message is empty'];
  if (GENERATED.test(header)) return [];
  const problems = [];
  if (!HEADER.test(header)) {
    problems.push(
      `header must look like "<type>(<scope>): <description>" with type one of: ${TYPES.join(', ')}`,
    );
  }
  if (header.length > MAX_HEADER_LENGTH) {
    problems.push(`header is ${header.length} characters; the limit is ${MAX_HEADER_LENGTH}`);
  }
  const second = lines[lines.indexOf(header) + 1];
  if (second !== undefined && second.trim() !== '')
    problems.push('leave a blank line between the header and the body');
  return problems;
}

function selfTest() {
  const cases = [
    ['feat(api): add audit chain verification', true],
    ['fix: handle empty case bundle', true],
    ['refactor(web)!: drop the legacy persona picker', true],
    ['chore(deps): bump fastify', true],
    ['Merge branch "main" into feat/x', true],
    ['fixup! feat(api): add audit chain verification', true],
    [
      '# comment line\nfeat(ci): add smoke test\n\nBody text.\n\nCo-authored-by: A <a@example.org>',
      true,
    ],
    ['Added some stuff', false],
    ['feat(API): uppercase scope', false],
    ['feat(api):no space after colon', false],
    ['feat(api): ', false],
    ['feature: unknown type', false],
    ['', false],
    [`feat: ${'x'.repeat(101)}`, false],
    ['feat(api): header\nbody without blank line', false],
  ];
  let failures = 0;
  for (const [message, valid] of cases) {
    const ok = (validate(message).length === 0) === valid;
    if (!ok) failures += 1;
    console.log(
      `${ok ? 'PASS' : 'FAIL'}  ${JSON.stringify(message.slice(0, 50))} -> ${valid ? 'valid' : 'invalid'}`,
    );
  }
  console.log(`check-commit-msg self-test: ${cases.length - failures}/${cases.length} passed`);
  return failures === 0;
}

function main() {
  const [arg] = process.argv.slice(2);
  if (arg === '--self-test') return selfTest() ? 0 : 1;
  if (!arg) {
    console.error('usage: node scripts/check-commit-msg.mjs <commit-message-file>');
    return 2;
  }
  const problems = validate(readFileSync(arg, 'utf8'));
  if (problems.length === 0) return 0;
  console.error('commit-msg: this message does not follow Conventional Commits:');
  for (const problem of problems) console.error(`  - ${problem}`);
  console.error(
    'Examples: "feat(api): add audit verification", "fix(web): keep focus after dialog close".',
  );
  return 1;
}

process.exitCode = main();
